      b = (b-1) & 0xFF;
    }
  } // block

  /**
   * `$D3AF`: what an object leaves behind when it moves — a column or a row of
   * blank glyphs where it was (`$D3EA`, `$D405`, `$D425`, `$D445`).
   */
  erase(ix, p) {
    var m = this.m;
    var a = (p.c-m[ix+0x0D]) & 0xFF;
    if (a === 0) {
