      }
      this.setChars(this.rd16(ix+0x10));
      this.rst10(0x10); this.rst10(m[ix+9]);
      var frame = (m[ix+6]+m[ix+0x12]) & 0xFF;
      if (frame === m[ix+0x13]) {
