      a = (m[ix]-m[ix+7]+1-m[0xDC0E]) & 0xFF;
      if (a >= 2) {
        continue;
      }
      this.events.push({id: 'beeper', de: 100, hl: 100});
      if (m[ix+8] !== 1) {
        m[0xDB42] = 0;                       // $D047
        this.events.push({id: 'beeper', de: 50, hl: 200});
        continue;
      }
      // $D01A: caught
      m[0xDB42] = (m[0xDB42]+1) & 0xFF;
      var e = m[ix+7];
      if (m[ix+2] !== 3) {
        e = (e+1) & 0xFF;
      }
      this.setChars(0x9F6C);
      this.block(0x20, m[ix], m[ix+1], m[ix+8], e);
      m[ix+0x0A] = 0;
    }
